long long n, c1, c2, result, power[20], sumArr[10];
vector<long long> bucket[10];

void doQuery(long long p, long long s) {
    for (int i = 0; i <= 6; ++i) {
        long long val = ((s - p * power[i]) % 998244353 + 998244353) % 998244353;
