void generateNumbers(long long x, int depth) {
    long long tmp = ((c1++ - x) % 998244353 + 998244353) % 998244353;
    sumArr[depth] = (sumArr[depth] + tmp) % 1000000007;
    bucket[depth].push_back(tmp);
